/**
 * 分片 → 文件。输入：清单 + 每个分片的字节（顺序同 manifest.chunks）。输出：每个文件一块独立的 buffer（顺序同 manifest.files）。
 * 分片是「所有文件按 offset 拼接」后的等长切片，所以一个分片可能横跨几个文件、一个文件也可能横跨几个分片。
 */
export function assembleFiles(m, chunks) {
    if (chunks.length !== m.chunks.length)
        throw new Error(`pack ${m.slug}: got ${chunks.length} chunks, manifest lists ${m.chunks.length}`);
    const bufs = m.files.map((f) => new Uint8Array(f.bytes));
    let offset = 0;
    for (let ci = 0; ci < chunks.length; ci++) {
        const bytes = chunks[ci];
        if (bytes.length !== m.chunks[ci].bytes)
            throw new Error(`pack ${m.slug}: ${m.chunks[ci].name} is ${bytes.length} bytes, manifest says ${m.chunks[ci].bytes}`);
        let pos = 0;
        while (pos < bytes.length) {
            const abs = offset + pos;
            const fi = m.files.findIndex((f) => abs >= f.offset && abs < f.offset + f.bytes);
            if (fi < 0)
                throw new Error(`pack ${m.slug}: ${m.chunks[ci].name} overflows the file table`);
            const f = m.files[fi], n = Math.min(f.offset + f.bytes - abs, bytes.length - pos);
            bufs[fi].set(bytes.subarray(pos, pos + n), abs - f.offset);
            pos += n;
        }
        offset += bytes.length;
    }
    if (offset !== m.totalBytes)
        throw new Error(`pack ${m.slug}: chunks add up to ${offset} bytes, manifest says ${m.totalBytes}`);
    return bufs;
}
/**
 * 给引擎配置里的包内文件名补上挂载目录。规则：配置里任何字符串值，按逗号拆开后**每一段都是包里的文件名或目录名**，就整段补目录；别的字符串原样。
 * （所以 "cpu"、"ja" 这种不会被误伤；"a.fst,b.fst" 这种逗号表会逐项补。）返回新对象，不改入参。
 */
export function resolvePackPaths(config, dir, files) {
    const names = new Set();
    for (const f of files) {
        names.add(f.path);
        const parts = f.path.split("/");
        for (let i = 1; i < parts.length; i++)
            names.add(parts.slice(0, i).join("/"));
    }
    const walk = (v) => {
        if (typeof v === "string") {
            if (!v)
                return v;
            const parts = v.split(",").map((s) => s.trim());
            return parts.every((p) => names.has(p)) ? parts.map((p) => `${dir}/${p}`).join(",") : v;
        }
        if (Array.isArray(v))
            return v.map(walk);
        if (v && typeof v === "object") {
            const o = {};
            for (const [k, x] of Object.entries(v))
                o[k] = walk(x);
            return o;
        }
        return v;
    };
    return walk(config);
}
